class CircuitBreaker {
public:
    enum State { CLOSED, OPEN, HALF_OPEN };

    CircuitBreaker(int threshold = 5, int timeout_sec = 30)
        : failure_threshold_(threshold), timeout_seconds_(timeout_sec),
          failure_count_(0), state_(CLOSED) {}

    bool allow_request() {
        std::lock_guard<std::mutex> lock(mutex_);
        if (state_ == CLOSED) return true;
        if (state_ == OPEN) {
            auto now = std::chrono::steady_clock::now();
            auto elapsed = std::chrono::duration_cast<std::chrono::seconds>(
                now - last_failure_time_).count();
            if (elapsed >= timeout_seconds_) {
                state_ = HALF_OPEN;
                return true;
            }
            return false;
        }
        return true; // HALF_OPEN allows one request
    }

    void record_success() {
        std::lock_guard<std::mutex> lock(mutex_);
        failure_count_ = 0;
        state_ = CLOSED;
    }

    void record_failure() {
        std::lock_guard<std::mutex> lock(mutex_);
        failure_count_++;
        last_failure_time_ = std::chrono::steady_clock::now();
        if (failure_count_ >= failure_threshold_) {
            state_ = OPEN;
        }
    }

    State get_state() const { return state_; }

private:
    int failure_threshold_;
    int timeout_seconds_;
    int failure_count_;
    State state_;
    std::chrono::steady_clock::time_point last_failure_time_;
    std::mutex mutex_;
};

class URIValidator {
public:
    struct ParsedURI {
        std::string scheme;
        std::string host;
        std::string port;
        std::string path;
        std::string query;
        std::string fragment;
    };

    static ParsedURI parse(const std::string& uri) {
        ParsedURI result;
        std::string remaining = uri;

        // Extract scheme
        auto scheme_end = remaining.find("://");
        if (scheme_end != std::string::npos) {
            result.scheme = remaining.substr(0, scheme_end);
            remaining = remaining.substr(scheme_end + 3);
        }

        // Extract fragment
        auto frag_pos = remaining.find('#');
        if (frag_pos != std::string::npos) {
            result.fragment = remaining.substr(frag_pos + 1);
            remaining = remaining.substr(0, frag_pos);
        }

        // Extract query
        auto query_pos = remaining.find('?');
        if (query_pos != std::string::npos) {
            result.query = remaining.substr(query_pos + 1);
            remaining = remaining.substr(0, query_pos);
        }

        // Extract path
        auto path_pos = remaining.find('/');
        if (path_pos != std::string::npos) {
            result.path = remaining.substr(path_pos);
            remaining = remaining.substr(0, path_pos);
        }

        // Extract host and port
        auto port_pos = remaining.rfind(':');
        if (port_pos != std::string::npos) {
            result.port = remaining.substr(port_pos + 1);
            result.host = remaining.substr(0, port_pos);
        } else {
            result.host = remaining;
        }

        return result;
    }

    static std::string normalize_host(const std::string& host) {
        std::string normalized = host;
        // Convert to lowercase for comparison
        std::transform(normalized.begin(), normalized.end(),
                      normalized.begin(), ::tolower);
        // Strip trailing dots (DNS root)
        while (!normalized.empty() && normalized.back() == '.') {
            normalized.pop_back();
        }
        return normalized;
    }

    static bool hosts_match(const std::string& uri_host, const std::string& allowed_host) {
        std::string norm_uri = normalize_host(uri_host);
        std::string norm_allowed = normalize_host(allowed_host);

        // Check if uri host ends with allowed host (subdomain matching)
        if (norm_uri.length() >= norm_allowed.length()) {
            size_t offset = norm_uri.length() - norm_allowed.length();
            if (norm_uri.substr(offset) == norm_allowed) {
                // Ensure it's a proper subdomain boundary or exact match
                if (offset == 0 || norm_uri[offset - 1] == '.') {
                    return true;
                }
            }
        }
        return false;
    }

    static bool validate_redirect_uri(const std::string& redirect_uri,
                                       const std::vector<std::string>& allowed_uris,
                                       size_t max_length) {
        if (redirect_uri.empty() || redirect_uri.length() > max_length) {
            return false;
        }

        // Reject URIs with userinfo component (anti-phishing)
        if (redirect_uri.find('@') != std::string::npos) {
            return false;
        }

        ParsedURI parsed = parse(redirect_uri);

        // Must be HTTPS
        if (parsed.scheme != "https") {
            return false;
        }

        // Check against allowed URIs
        for (const auto& allowed : allowed_uris) {
            ParsedURI allowed_parsed = parse(allowed);

            if (hosts_match(parsed.host, allowed_parsed.host)) {
                // Verify path prefix matches
                if (parsed.path.find(allowed_parsed.path) == 0 ||
                    allowed_parsed.path.empty()) {
                    return true;
                }
            }
        }

        return false;
    }
};

class EmailService {
public:
    EmailService(const OAuthConfig& config)
        : config_(config), auth_breaker_(3, 60), send_breaker_(5, 30) {}

    struct AuthResult {
        bool success;
        std::string redirect_location;
        std::string error;
    };

    AuthResult handle_oauth_callback(const std::string& code,
                                      const std::string& state,
                                      const std::string& redirect_uri) {
        AuthResult result{false, "", ""};

        if (!auth_breaker_.allow_request()) {
            result.error = "Service temporarily unavailable";
            return result;
        }

        // Validate the redirect URI
        if (!URIValidator::validate_redirect_uri(
                redirect_uri, config_.allowed_redirect_uris,
                config_.max_redirect_length)) {
            auth_breaker_.record_failure();
            result.error = "Invalid redirect URI";
            return result;
        }

        // Simulate token exchange
        if (exchange_token(code, redirect_uri)) {
            auth_breaker_.record_success();
            result.success = true;
            result.redirect_location = redirect_uri;
        } else {
            auth_breaker_.record_failure();
            result.error = "Token exchange failed";
        }

        return result;
    }

    bool send_email(const std::string& to, const std::string& subject,
                   const std::string& body) {
        if (!send_breaker_.allow_request()) {
            return false;
        }

        // Simulate sending
        bool success = do_send(to, subject, body);
        if (success) {
            send_breaker_.record_success();
        } else {
            send_breaker_.record_failure();
        }
        return success;
    }

private:
    bool exchange_token(const std::string& code, const std::string& redirect_uri) {
        // Simulated token exchange
        return !code.empty() && !redirect_uri.empty();
    }

    bool do_send(const std::string& to, const std::string& subject,
                const std::string& body) {
        return !to.empty() && !subject.empty();
    }

    OAuthConfig config_;
    CircuitBreaker auth_breaker_;
    CircuitBreaker send_breaker_;
};

